create table analyse_risque_epis (analyse_risque_id varchar(255) not null, epi_id varchar(255) not null, primary key (analyse_risque_id, epi_id));
create table analyse_risque_mesures (analyse_risque_id varchar(255) not null, mesure_id varchar(255) not null, primary key (analyse_risque_id, mesure_id));
