create table analyses_ia (taux_confiance float(53), date_analyse timestamp(6), temps_execution bigint, commentaireia TEXT, id varchar(255) not null, json_extraction TEXT, modele_utilise varchar(255), ocr_text TEXT, permis_id varchar(255) unique, resultat varchar(255), version_modele varchar(255), primary key (id));
create table analyses_risques (date_analyse timestamp(6), analyseur_id varchar(255), commentaire TEXT, id varchar(255) not null, visite_prealable_id varchar(255) unique, primary key (id));
create table audit_logs (date timestamp(6), action varchar(255) not null, adresseip varchar(255), id varchar(255) not null, navigateur varchar(255), resultat varchar(255) check (resultat in ('SUCCES','ECHEC')), systeme_exploitation varchar(255), utilisateur_id varchar(255), primary key (id));
create table autorisations_travail (date_debut date, date_fin date, heure_debut time(6), heure_fin time(6), version integer, date_creation timestamp(6), date_liberation_verrou timestamp(6), date_modification timestamp(6), date_prise_verrou timestamp(6), numero varchar(30) not null unique, bt_id varchar(255) unique, description_travaux varchar(255), di_id varchar(255) unique, etat_verrou varchar(255) check (etat_verrou in ('LIBRE','EN_COURS_EDITION','TRANSFERE')), id varchar(255) not null, objet varchar(255) not null, ot_id varchar(255) unique, proprietaire_brouillon_id varchar(255), statut varchar(255) check (statut in ('BROUILLON','SOUMISE','VALIDEE','REJETEE','RENOUVELEE','CLOTUREE','ANNULEE')), primary key (id));
create table bons_travail (date_emission timestamp(6), numero varchar(30) not null unique, demandeur_id varchar(255), description TEXT, entreprise_externe_id varchar(255) not null, id varchar(255) not null, installation_id varchar(255), niveau_intervention varchar(255) not null check (niveau_intervention in ('NIVEAU_1','NIVEAU_2')), objet varchar(255) not null, statut varchar(255) not null check (statut in ('BROUILLON','SOUMIS','EN_COURS','EN_ATTENTE_VISITE','EN_ATTENTE_ANALYSE','AT_GENEREE','CLOS','ANNULE')), type_intervention varchar(255) not null check (type_intervention in ('CURATIVE','PREVENTIVE','PLANIFIEE','URGENTE','EXCEPTIONNELLE','MECANIQUE')), visite_prealable_id varchar(255) unique, primary key (id));
create table demandes_intervention (date_demande timestamp(6), numero varchar(30) not null unique, demandeur_id varchar(255), description TEXT, equipement_id varchar(255), id varchar(255) not null, installation_id varchar(255), niveau_intervention varchar(255) not null check (niveau_intervention in ('NIVEAU_1','NIVEAU_2')), objet varchar(255) not null, priorite varchar(255), statut varchar(255) not null check (statut in ('BROUILLON','SOUMIS','EN_COURS','EN_ATTENTE_VISITE','EN_ATTENTE_ANALYSE','AT_GENEREE','CLOS','ANNULE')), type_intervention varchar(255) not null check (type_intervention in ('CURATIVE','PREVENTIVE','PLANIFIEE','URGENTE','EXCEPTIONNELLE','MECANIQUE')), visite_prealable_id varchar(255) unique, primary key (id));
create table entreprises_externes (adresse varchar(255), id varchar(255) not null, nom_entreprise varchar(255) not null, responsable varchar(255), telephone varchar(255), primary key (id));
create table epis (descriptionepi varchar(255), id varchar(255) not null, nomepi varchar(255) not null, primary key (id));
create table equipements (code_equipement varchar(255) not null unique, description_equipement varchar(255), id varchar(255) not null, installation_id varchar(255), nom_equipement varchar(255) not null, primary key (id));
create table fichiers_joints (date_import timestamp(6), taille bigint, hashsha256 varchar(255), id varchar(255) not null, nom varchar(255) not null, path varchar(255) not null, permis_id varchar(255) unique, type varchar(255), uploaded_by varchar(255), primary key (id));
create table historiques_at (date_action timestamp(6), action varchar(255) not null check (action in ('CREATION','MODIFICATION','AUTO_SAVE','TRANSFERT','SOUMISSION','VALIDATION','REFUS','RENOUVELLEMENT','CLOTURE','EXPORT_PDF','ANNULATION')), ancien_statut varchar(255) check (ancien_statut in ('BROUILLON','SOUMISE','VALIDEE','REJETEE','RENOUVELEE','CLOTUREE','ANNULEE')), at_id varchar(255) not null, commentaire varchar(255), id varchar(255) not null, nouveau_statut varchar(255) check (nouveau_statut in ('BROUILLON','SOUMISE','VALIDEE','REJETEE','RENOUVELEE','CLOTUREE','ANNULEE')), utilisateur_id varchar(255), primary key (id));
create table installations (atelier varchar(255), code_installation varchar(255) not null unique, id varchar(255) not null, localisation varchar(255), nom_installation varchar(255) not null, service_id varchar(255), primary key (id));
create table mesures_preparation (description_mesure varchar(255), id varchar(255) not null, nom_mesure varchar(255) not null, primary key (id));
create table moyens_acces (description_moyen varchar(255), id varchar(255) not null, nom_moyen varchar(255) not null, primary key (id));
create table notifications (lu boolean not null, date_creation timestamp(6), date_lecture timestamp(6), id varchar(255) not null, lien varchar(255), message varchar(255) not null, titre varchar(255) not null, type varchar(255), utilisateur_id varchar(255) not null, primary key (id));
create table ordres_travail (date_creation timestamp(6), date_execution timestamp(6), numero varchar(30) not null unique, demandeur_id varchar(255), description TEXT, id varchar(255) not null, installation_id varchar(255), niveau_intervention varchar(255) not null check (niveau_intervention in ('NIVEAU_1','NIVEAU_2')), objet varchar(255) not null, statut varchar(255) not null check (statut in ('BROUILLON','SOUMIS','EN_COURS','EN_ATTENTE_VISITE','EN_ATTENTE_ANALYSE','AT_GENEREE','CLOS','ANNULE')), type_intervention varchar(255) not null check (type_intervention in ('CURATIVE','PREVENTIVE','PLANIFIEE','URGENTE','EXCEPTIONNELLE','MECANIQUE')), visite_prealable_id varchar(255) unique, primary key (id));
create table permis (date_emission date, date_expiration date, est_obligatoire boolean, at_id varchar(255), commentaire TEXT, id varchar(255) not null, numero varchar(255), statut_verification varchar(255) check (statut_verification in ('A_VERIFIER','CONFORME','NON_CONFORME','EXPIRE','INVALIDE')), type varchar(255) not null check (type in ('FEU','FOUILLE','TRAVAIL_HAUTEUR','ESPACE_CONFINE','CONSIGNATION')), primary key (id));
create table permissions (description varchar(255), id varchar(255) not null, nom varchar(255) not null unique, primary key (id));
create table photos (ordre integer, date_creation timestamp(6), taille bigint, id varchar(255) not null, legende varchar(255), nom varchar(255) not null, path varchar(255) not null, type_mime varchar(255), visite_prealable_id varchar(255), primary key (id));
create table refresh_tokens (revoked boolean not null, date_creation timestamp(6) with time zone not null, expiry_date timestamp(6) with time zone not null, token varchar(512) not null unique, adresseip varchar(255), id varchar(255) not null, user_agent varchar(255), utilisateur_id varchar(255) not null, primary key (id));
create table risques (description_risque varchar(255), id varchar(255) not null, niveau varchar(255), nom_risque varchar(255) not null, primary key (id));
create table role_permissions (permission_id varchar(255) not null, role_id varchar(255) not null, primary key (permission_id, role_id));
create table roles (description varchar(255), id varchar(255) not null, nom varchar(255) not null unique, primary key (id));
create table services (code_service varchar(255) not null unique, description_service varchar(255), id varchar(255) not null, nom_service varchar(255) not null, zone_id varchar(255), primary key (id));
create table utilisateur_roles (role_id varchar(255) not null, utilisateur_id varchar(255) not null, primary key (role_id, utilisateur_id));
create table utilisateurs (actif boolean not null, compte_verrouille boolean not null, compteur_echecs_connexion integer not null, mot_de_passe_expire boolean not null, date_creation timestamp(6) not null, date_modification timestamp(6), derniere_connexion timestamp(6), email varchar(255) not null unique, id varchar(255) not null, matricule varchar(255) not null unique, mot_de_passe varchar(255) not null, nom varchar(255) not null, photo varchar(255), prenom varchar(255) not null, telephone varchar(255), primary key (id));
create table visas (ordre integer, date_signature timestamp(6), date_visa timestamp(6), adresseip varchar(255), at_id varchar(255) not null, commentaire varchar(255), id varchar(255) not null, navigateur varchar(255), signature_hash varchar(255), signature_path varchar(255), statut varchar(255) not null check (statut in ('EN_ATTENTE','VALIDE','REFUSE','VALIDATION','SIGNATURE','REFUS')), utilisateur_id varchar(255) not null, primary key (id));
create table visite_prealable_risques (risque_id varchar(255) not null, visite_prealable_id varchar(255) not null, primary key (risque_id, visite_prealable_id));
create table visites_prealables (effectuee boolean not null, latitude float(53), longitude float(53), date_heure_debut timestamp(6), date_heure_fin timestamp(6), commentaire TEXT, id varchar(255) not null, visiteur_id varchar(255), primary key (id));
create table workflows_at (actif boolean, ordre_validation integer, validation_obligatoire boolean, action varchar(255) not null check (action in ('CREATION','MODIFICATION','AUTO_SAVE','TRANSFERT','SOUMISSION','VALIDATION','REFUS','RENOUVELLEMENT','CLOTURE','EXPORT_PDF','ANNULATION')), etat_arrivee varchar(255) not null check (etat_arrivee in ('BROUILLON','SOUMISE','VALIDEE','REJETEE','RENOUVELEE','CLOTUREE','ANNULEE')), etat_depart varchar(255) not null check (etat_depart in ('BROUILLON','SOUMISE','VALIDEE','REJETEE','RENOUVELEE','CLOTUREE','ANNULEE')), id varchar(255) not null, notification_suivante varchar(255), role_autorise varchar(255), role_suivant varchar(255), primary key (id));
create table zones (code_zone varchar(255) not null unique, description_zone varchar(255), id varchar(255) not null, nom_zone varchar(255) not null, primary key (id));
