create table ordres_travail (date_creation timestamp(6), date_execution timestamp(6), numero varchar(30) not null unique, demandeur_id varchar(255), description TEXT, id varchar(255) not null, installation_id varchar(255), niveau_intervention varchar(255) not null check (niveau_intervention in ('NIVEAU_1','NIVEAU_2')), objet varchar(255) not null, statut varchar(255) not null check (statut in ('BROUILLON','SOUMIS','EN_COURS','EN_ATTENTE_VISITE','EN_ATTENTE_ANALYSE','AT_GENEREE','CLOS','ANNULE')), type_intervention varchar(255) not null check (type_intervention in ('CURATIVE','PREVENTIVE','PLANIFIEE','URGENTE','EXCEPTIONNELLE','MECANIQUE')), visite_prealable_id varchar(255) unique, primary key (id));
create table permis (date_emission date, date_expiration date, est_obligatoire boolean, at_id varchar(255), commentaire TEXT, id varchar(255) not null, numero varchar(255), statut_verification varchar(255) check (statut_verification in ('A_VERIFIER','CONFORME','NON_CONFORME','EXPIRE','INVALIDE')), type varchar(255) not null check (type in ('FEU','FOUILLE','TRAVAIL_HAUTEUR','ESPACE_CONFINE','CONSIGNATION')), primary key (id));
create table permissions (description varchar(255), id varchar(255) not null, nom varchar(255) not null unique, primary key (id));
create table photos (ordre integer, date_creation timestamp(6), taille bigint, id varchar(255) not null, legende varchar(255), nom varchar(255) not null, path varchar(255) not null, type_mime varchar(255), visite_prealable_id varchar(255), primary key (id));
