create table analyses_risques (date_analyse timestamp(6), analyseur_id varchar(255), commentaire TEXT, id varchar(255) not null, visite_prealable_id varchar(255) unique, primary key (id));
create table audit_logs (date timestamp(6), action varchar(255) not null, adresseip varchar(255), id varchar(255) not null, navigateur varchar(255), resultat varchar(255) check (resultat in ('SUCCES','ECHEC')), systeme_exploitation varchar(255), utilisateur_id varchar(255), primary key (id));
create table autorisations_travail (date_debut date, date_fin date, heure_debut time(6), heure_fin time(6), version integer, date_creation timestamp(6), date_liberation_verrou timestamp(6), date_modification timestamp(6), date_prise_verrou timestamp(6), numero varchar(30) not null unique, bt_id varchar(255) unique, description_travaux varchar(255), di_id varchar(255) unique, etat_verrou varchar(255) check (etat_verrou in ('LIBRE','EN_COURS_EDITION','TRANSFERE')), id varchar(255) not null, objet varchar(255) not null, ot_id varchar(255) unique, proprietaire_brouillon_id varchar(255), statut varchar(255) check (statut in ('BROUILLON','SOUMISE','VALIDEE','REJETEE','RENOUVELEE','CLOTUREE','ANNULEE')), primary key (id));
create table bons_travail (date_emission timestamp(6), numero varchar(30) not null unique, demandeur_id varchar(255), description TEXT, entreprise_externe_id varchar(255) not null, id varchar(255) not null, installation_id varchar(255), niveau_intervention varchar(255) not null check (niveau_intervention in ('NIVEAU_1','NIVEAU_2')), objet varchar(255) not null, statut varchar(255) not null check (statut in ('BROUILLON','SOUMIS','EN_COURS','EN_ATTENTE_VISITE','EN_ATTENTE_ANALYSE','AT_GENEREE','CLOS','ANNULE')), type_intervention varchar(255) not null check (type_intervention in ('CURATIVE','PREVENTIVE','PLANIFIEE','URGENTE','EXCEPTIONNELLE','MECANIQUE')), visite_prealable_id varchar(255) unique, primary key (id));
create table demandes_intervention (date_demande timestamp(6), numero varchar(30) not null unique, demandeur_id varchar(255), description TEXT, equipement_id varchar(255), id varchar(255) not null, installation_id varchar(255), niveau_intervention varchar(255) not null check (niveau_intervention in ('NIVEAU_1','NIVEAU_2')), objet varchar(255) not null, priorite varchar(255), statut varchar(255) not null check (statut in ('BROUILLON','SOUMIS','EN_COURS','EN_ATTENTE_VISITE','EN_ATTENTE_ANALYSE','AT_GENEREE','CLOS','ANNULE')), type_intervention varchar(255) not null check (type_intervention in ('CURATIVE','PREVENTIVE','PLANIFIEE','URGENTE','EXCEPTIONNELLE','MECANIQUE')), visite_prealable_id varchar(255) unique, primary key (id));
create table entreprises_externes (adresse varchar(255), id varchar(255) not null, nom_entreprise varchar(255) not null, responsable varchar(255), telephone varchar(255), primary key (id));
create table epis (descriptionepi varchar(255), id varchar(255) not null, nomepi varchar(255) not null, primary key (id));
create table equipements (code_equipement varchar(255) not null unique, description_equipement varchar(255), id varchar(255) not null, installation_id varchar(255), nom_equipement varchar(255) not null, primary key (id));
